"""Audit every exported declaration and record its source hash and proof axioms."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import re
import subprocess
import sys

ROOT = Path(__file__).resolve().parents[1]
sys.stdout.reconfigure(encoding="utf-8")
parser = argparse.ArgumentParser()
parser.add_argument("--lean-bin", type=Path, default=Path.home()/".cache/lean4/lean-4.34.0-windows/bin")
parser.add_argument("--packages", type=Path, default=ROOT.parent/"quartic_dependence/.lake/packages")
parser.add_argument("--timeout", type=int, default=600)
args = parser.parse_args()
build = ROOT/".lake/build/lib/lean"
env = os.environ.copy()
env["LEAN_PATH"] = os.pathsep.join(map(str, [build, ROOT] + [p/".lake/build/lib/lean" for p in args.packages.iterdir() if p.is_dir()]))
names, hashes, theorems, compilations = [], {}, [], []
for path in sorted((ROOT/"DimensionFourDependence").glob("*.lean")):
    source = path.read_text(encoding="utf-8")
    namespace = re.search(r"^namespace (\S+)", source, re.M).group(1)
    # All files use one enclosing namespace. Comments are stripped with nesting.
    clean, index, depth = [], 0, 0
    while index < len(source):
        if source[index:index+2] == "/-":
            depth += 1; index += 2
        elif depth and source[index:index+2] == "-/":
            depth -= 1; index += 2
        elif depth:
            index += 1
        elif source[index:index+2] == "--":
            index = source.find("\n", index)
            if index < 0:
                break
        else:
            clean.append(source[index]); index += 1
    clean = "".join(clean)
    assert not re.search(r"\b(sorry|admit|axiom|unsafe)\b", clean), path
    for kind, name in re.findall(r"^(?:@\[[^\n]*\]\s+)?(?:noncomputable )?(def|abbrev|theorem|lemma|structure)\s+([^\s{(:]+)", clean, re.M):
        full = namespace + "." + name
        names.append(full)
        if kind in ("theorem", "lemma"):
            theorems.append(full)
    hashes[path.relative_to(ROOT).as_posix()] = hashlib.sha256(path.read_bytes()).hexdigest()
    result = json.loads((ROOT/"validation"/(path.stem+".json")).read_text(encoding="utf-8"))
    assert result["exit_code"] == 0 and result["source_sha256"] == hashes[path.relative_to(ROOT).as_posix()], "Missing current successful compilation: " + str(path)
    compilations.append(result)
    olean = build/path.relative_to(ROOT).with_suffix(".olean")
    assert olean.stat().st_mtime_ns >= path.stat().st_mtime_ns, "Stale proof: " + str(path)
main = ROOT/"DimensionFourDependence.lean"
hashes[main.name] = hashlib.sha256(main.read_bytes()).hexdigest()
main_result = json.loads((ROOT/"validation/Main.json").read_text(encoding="utf-8"))
assert main_result["exit_code"] == 0 and main_result["source_sha256"] == hashes[main.name], "The umbrella module has not been checked in its current form"
compilations.append(main_result)
assert (build/"DimensionFourDependence.olean").stat().st_mtime_ns >= main.stat().st_mtime_ns
audit_source = 'import DimensionFourDependence\n\n' + "\n".join("#print axioms " + name for name in names) + "\n"
(ROOT/"validation/axioms.lean").write_text(audit_source, encoding="utf-8")
r = subprocess.run([str(args.lean_bin/"lean.exe"), str(ROOT/"validation/axioms.lean")], cwd=ROOT, env=env, capture_output=True, encoding="utf-8", timeout=args.timeout)
log = r.stdout + r.stderr
(ROOT/"validation/axioms.log").write_text(log, encoding="utf-8")
assert r.returncode == 0, log
axioms = {name: re.findall(r"[A-Za-z_][A-Za-z0-9_.]*", values) for name,values in re.findall(r"'([^']+)' depends on axioms:\s*\[([^\]]*)\]", log)}
axioms.update({name: [] for name in re.findall(r"'([^']+)' does not depend on any axioms", log)})
assert set(axioms) == set(names), "Missing audit entries"
allowed = {"propext", "Classical.choice", "Quot.sound"}
assert all(set(values) <= allowed for values in axioms.values()), axioms
assert "DimensionFourDependence.Shear.proposition_6_4_general" in axioms
